--- from: Assets/BundleResources/Prefabs/ResidentEvent/ResdientFeedbackDialog.prefab > name: ResdientFeedbackDialog
---@class VipFeedbackPanel
---@field Env                           	VipFeedbackPanel                        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field ImgBg                         	UnityEngine.RectTransform               	@ 0    
---@field RightRoot                     	UnityEngine.RectTransform               	@ 1    
---@field TxtDesc                       	UnityEngine.RectTransform               	@ 2    
---@field CommonGoodsListLight          	UnityEngine.RectTransform               	@ 3    
---@field FontStyleButton               	UnityEngine.RectTransform               	@ 4    
---@field CommonRedPoint                	UnityEngine.RectTransform               	@ 5    
local VipFeedbackPanel = Class('VipFeedbackPanel')

function VipFeedbackPanel:__init()
    self.data = nil
end

function VipFeedbackPanel:__delete()
    self.data = nil
end

function VipFeedbackPanel:Awake()
    CfUtils.SetActive(self.RightRoot, false)
    SetButtonAction(self.FontStyleButton, function()
        if not CfUtils.IsActive(self.RightRoot) then
            return
        end
        if not self.data then
            return
        end
        if checkNumber(self.data.drawn) == 1 then
            CfUtils.OpenURL(checkString(self.data.link))
            --GameUtils.Toast(localize("当前奖励已领取"))
            return
        end
        CfUtils.OpenURL(checkString(self.data.link))
        --领取
        GameUtils.Request("OverseaPlayer/drawVipRewards", {}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                self.data.drawn = 1 ---已领取
                local rewardList = checkTable(response.data.rewards)
                if table.count(rewardList) > 0 then
                    GoodsUtils.DrawRewards(rewardList, true)
                    CfUtils.DialogOpen(Constants.UITypeIds.UICommonRewardPop, {rewards = rewardList})
                end
                self:RefreshUI()
                GameUtils.SetRedPointNum(Constants.RedPointConst.VipFund, 0)
                GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.VipFund)
            end
        end)
    end)
end

function VipFeedbackPanel:Refresh()
    GameUtils.Request("OverseaPlayer/vip", {}, function(request, response)
        if checkNumber(response.errCode) == 0 then
            self.data = checkTable(response.data)
            CfUtils.SetActive(self.RightRoot, true)
            self:RefreshUI()
        end
    end)
end

function VipFeedbackPanel:RefreshUI()
    ---刷新界面ui
    CfUtils.FillText(self.TxtDesc, self.data.detail)
    ---@type CommonGoodsListLight
    local rewardEnv = CfUtils.GetLuaScr(self.CommonGoodsListLight, "Game.Behaviours.CommonGoodsListLight")
    rewardEnv:FreshBaseUI(checkTable(self.data.rewards), false, checkNumber(self.data.drawn) == 1)
    ---@type Game.Native.Common.FontStyleButton
    local fontStyleBtn = self.FontStyleButton:GetComponent(typeof(FontStyleButton))
    local textTrans = fontStyleBtn.transform:Find("Text")
    if textTrans then
        CfUtils.SetUISwitchText(textTrans, checkNumber(self.data.drawn) == 1 and 3 or 2)
    end
    CfUtils.SetActive(self.CommonRedPoint, checkNumber(self.data.drawn) == 0)
end

function VipFeedbackPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return VipFeedbackPanel